def _en(key, hindi_of):
    """Plain English word for a class key."""
    if key == "i_alphabet":
        return "I"
    return key.replace("_", " ") if key not in ("big_large", "small_little") else key.split("_")[0]


def _cap(s):
    return s[:1].upper() + s[1:] if s else s


def _article(noun):
    return "an" if noun[:1] in "aeiou" else "a"


def _complete(cl):
    """True when a clause already has a subject/topic and something said about it."""
    content = [c for c in cl if c not in POSS and c != "please" and c not in TIME]
    return len(content) >= 2 or (len(content) == 1 and content[0] not in SUBJ and content[0] not in WH)


def _split_clauses(keys):
    """Greetings/phrases stand alone; a question word closes a clause (ISL is wh-final) unless it opens one;
    a new subject, 'please' or another urgent word after a complete clause starts a new one."""
    clauses, cur = [], []
    for k in keys:
        if k in PHRASE:
            if cur:
                clauses.append(cur)
            clauses.append([k]); cur = []
        elif k in WH and cur and not any(c in WH for c in cur):
            # the wh-word asks about the trailing noun phrase; anything before it is its own statement
            j = len(cur)
            while j > 0 and (cur[j - 1] in NOUNS or cur[j - 1] in POSS):
                j -= 1
            head, tail = cur[:j], cur[j:]
            if tail and head and _complete(head):
                clauses.append(head); cur = tail
            cur.append(k); clauses.append(cur); cur = []
        elif k in WH and cur:
            clauses.append(cur); cur = [k]
        elif (k in SUBJ or k == "please") and cur and _complete(cur) and not (cur[0] in WH and len(cur) < 3):
            clauses.append(cur); cur = [k]
        elif k in URGENT and cur and any(c in URGENT for c in cur):
            clauses.append(cur); cur = [k]
        else:
            cur.append(k)
    if cur:
        clauses.append(cur)
    return clauses


def _np(keys, hindi_of):
    """(possessive?) + noun words -> (english NP, hindi NP)."""
    en, hi, fem = [], [], False
    nouns = [k for k in keys if k not in POSS]
    if nouns and nouns[-1] in FEMININE_HI:
        fem = True
    for k in keys:
        if k in POSS:
            en.append(POSS[k][0]); hi.append(POSS[k][2] if fem else POSS[k][1])
        else:
            en.append(_en(k, hindi_of)); hi.append(hindi_of(k))
    e = " ".join(en)
    if e and not any(k in POSS for k in keys):
        e = "the " + e
    return e, " ".join(hi)


def _realise(cl, hindi_of):
    """One clause -> (english, hindi, is_urgent)."""
    urgent = any(k in URGENT for k in cl)
    if len(cl) == 1 and cl[0] in PHRASE:
        return PHRASE[cl[0]] + (False,)
    please = "please" in cl
    cl = [k for k in cl if k != "please"]
    if not cl:
        return "Please.", "कृपया।", False
    times = [k for k in cl if k in TIME]
    cl = [k for k in cl if k not in TIME]
    t_en = " ".join(TIME[k][0] for k in times)
    t_hi = " ".join(TIME[k][1] for k in times)

    def finish(en, hi, q=False, excl=False):
        en = en.strip()
        if t_en:
            en = f"{_cap(t_en)}, {en[:1].lower() + en[1:] if not en.startswith('I ') else en}"
            hi = f"{t_hi} {hi}"
        end_en, end_hi = ("?", "?") if q else (("!", "!") if excl else (".", "।"))
        en, hi = en.rstrip(".!?"), hi.rstrip("।!?")
        if please and not q and not en.lower().startswith("please"):
            en, hi = f"Please {en[:1].lower() + en[1:] if not en.startswith('I ') else en}", f"कृपया {hi}"
        return _cap(en) + end_en, hi + end_hi, urgent

    if not cl:
        return finish(t_en or "", t_hi or "")
    # please + adverb  ("PLEASE SLOW" -> "Please speak slowly.")
    if please and len(cl) == 1 and cl[0] in PLEASE_ADVERB:
        return PLEASE_ADVERB[cl[0]] + (False,)
    # fingerspelling / numbers
    if all(k in LETTERS for k in cl) and len(cl) > 1:
        w = "".join("i" if k == "i_alphabet" else k for k in cl).upper()
        return finish(f"{w}", w)
    if all(k in DIGITS for k in cl):
        n = "".join(cl)
        return finish(n, n)
    # single emergency word
    if len(cl) == 1 and cl[0] in EMERGENCY:
        e, h = EMERGENCY[cl[0]]
        if t_en:
            e, h = f"{_cap(t_en)}, {e[:1].lower() + e[1:]}", f"{t_hi} {h}"
        return e, h, urgent or cl[0] in ("doctor", "hospital")
    subj = next((k for k in cl if k in SUBJ), None)
    rest = [k for k in cl if k != subj]
    wh = next((k for k in rest if k in WH), None)
    if wh:
        rest = [k for k in rest if k != wh]
        w_en, w_hi = WH[wh]
        if wh == "how_many":
            n_en, n_hi = _np(rest, hindi_of) if rest else ("", "")
            n_en = n_en.replace("the ", "")
            n_en = n_en + ("s" if n_en and not n_en.endswith("s") else "")
            return finish(f"How many {n_en}".strip(), f"{n_hi} कितने हैं".strip(), q=True)
        if subj:
            s_en, s_hi, be_en, be_hi, _ = SUBJ[subj]
            if rest:
                p_en = " ".join(_en(k, hindi_of) for k in rest); p_hi = " ".join(hindi_of(k) for k in rest)
                if wh == "what":   # "YOU DEAF WHAT" is a yes/no question in ISL
                    return finish(f"{_cap(be_en)} {s_en} {p_en}", f"क्या {s_hi} {p_hi} {be_hi}", q=True)
                return finish(f"{w_en} {be_en} {s_en} {p_en}", f"{s_hi} {p_hi} {w_hi} {be_hi}", q=True)
            return finish(f"{w_en} {be_en} {s_en}", f"{s_hi} {w_hi} {be_hi}", q=True)
        if rest:
            n_en, n_hi = _np(rest, hindi_of)
            if wh == "which":
                return finish(f"Which {n_en.replace('the ', '')}", f"कौन सा {n_hi}", q=True)
            plural = n_en.endswith("things")
            return finish(f"{w_en} {'are' if plural else 'is'} {n_en}", f"{n_hi} {w_hi} है", q=True)
        return finish(w_en, w_hi, q=True)
    if subj:
        s_en, s_hi, be_en, be_hi, dat_hi = SUBJ[subj]
        if not rest:
            return finish(_cap(s_en), s_hi)
        head = rest[-1]
        # "I need a doctor"
        if all(k in NEEDABLE or k in POSS for k in rest) and head not in ACTIONS and head != "rest":
            n_en, n_hi = _np(rest, hindi_of)
            if n_en.startswith("the "):
                n_en = n_en[4:] if n_en[4:] in ("help", "cpr", "rest") else f"{_article(n_en[4:])} {n_en[4:]}"
            need = "needs" if be_en == "is" else "need"
            return finish(f"{_cap(s_en)} {need} {n_en}", f"{dat_hi} {n_hi} चाहिए", excl=urgent)
        if head in STATE_HI_DATIVE and len(rest) == 1:
            e, h = STATE_HI_DATIVE[head]
            return finish(f"{_cap(s_en)} {be_en} {e}", f"{dat_hi} {h}", excl=urgent)
        if head in ACTIONS:
            v_en, v_hi = ACTIONS[head]
            if please or subj in ("you", "you_all", "yourself"):
                return finish(f"{v_en}", IMPERATIVE_HI.get(head, v_hi))
            v3 = v_en + ("s" if be_en == "is" else "")
            obj = [k for k in rest[:-1]]
            o_en = (" " + _np(obj, hindi_of)[0]) if obj else ""
            o_hi = (_np(obj, hindi_of)[1] + " ") if obj else ""
            return finish(f"{_cap(s_en)} {v3}{o_en}", f"{s_hi} {o_hi}{v_hi.replace('ना', 'ता')} {be_hi}")
        p_en = " ".join(_en(k, hindi_of) for k in rest)
        p_hi = " ".join(hindi_of(k) for k in rest)
        if len(rest) > 1 and not any(k in NOUNS or k in POSS for k in rest):
            p_en = ", ".join(_en(k, hindi_of) for k in rest[:-1]) + " and " + _en(rest[-1], hindi_of)
            p_hi = ", ".join(hindi_of(k) for k in rest[:-1]) + " और " + hindi_of(rest[-1])
        if head in NOUNS and len(rest) == 1:
            p_en = f"{_article(p_en)} {p_en}"
        return finish(f"{_cap(s_en)} {be_en} {p_en}", f"{s_hi} {p_hi} {be_hi}")
    # no subject
    if len(cl) == 1:
        k = cl[0]
        if k in ACTIONS:
            return finish(ACTIONS[k][0], IMPERATIVE_HI.get(k, ACTIONS[k][1]), excl=False)
        return finish(_cap(_en(k, hindi_of)), hindi_of(k))
    nouns = [k for k in cl if k in NOUNS or k in POSS]
    others = [k for k in cl if k not in nouns]
    if nouns and others and cl[:len(nouns)] == nouns:
        n_en, n_hi = _np(nouns, hindi_of)
        a_en = " and ".join(_en(k, hindi_of) for k in others); a_hi = " और ".join(hindi_of(k) for k in others)
        plural = n_en.endswith("things")
        return finish(f"{_cap(n_en)} {'are' if plural else 'is'} {a_en}", f"{n_hi} {a_hi} है", excl=urgent)
    if all(k in URGENT or k in EMERGENCY for k in cl):
        parts = [EMERGENCY[k] for k in cl]
        return " ".join(p[0] for p in parts), " ".join(p[1] for p in parts), True
    return finish(_cap(" ".join(_en(k, hindi_of) for k in cl)), " ".join(hindi_of(k) for k in cl), excl=urgent)


def compose(keys, hindi_of=lambda k: k):
    """List of class keys (signing order) -> dict(en, hi, urgent, clauses). Fully offline and deterministic."""
    keys = [k for k in keys if k and k != "__reject__"]
    if not keys:
        return dict(en="", hi="", urgent=False, clauses=[])
    outs = [_realise(cl, hindi_of) for cl in _split_clauses(keys)]
    return dict(en=" ".join(o[0] for o in outs), hi=" ".join(o[1] for o in outs),
                urgent=any(o[2] for o in outs), clauses=[(o[0], o[1]) for o in outs])


def polish_with_claude(glosses, draft_en, timeout=8.0):
    """Optional: refine the sentence with Claude when ANTHROPIC_API_KEY is set. Returns dict(en, hi) or None."""
    if not os.environ.get("ANTHROPIC_API_KEY"):
        return None
    try:
        import anthropic
        client = anthropic.Anthropic(timeout=timeout, max_retries=1)
        prompt = ("You convert Indian Sign Language (ISL) gloss sequences into what the signer most likely means. "
                  "ISL is topic-comment and question-final and omits articles and the verb 'to be'. "
                  "Stay faithful: do not add facts that are not implied by the glosses.\n"
                  f"Glosses in signing order: {' '.join(glosses)}\nRule-based draft: {draft_en}\n"
                  'Reply with only a JSON object: {"en": "<natural English>", "hi": "<natural Hindi in Devanagari>"}')
        resp = client.messages.create(model="claude-opus-5-5", max_tokens=1024, output_config={"effort": "low"},
                                      messages=[{"role": "user", "content": prompt}])
        if resp.stop_reason == "refusal":
            return None
        text = "".join(b.text for b in resp.content if b.type == "text")
        m = re.search(r"\{.*\}", text, re.S)
        out = json.loads(m.group(0)) if m else None
        return out if out and out.get("en") else None
    except Exception:
        return None


