# ----------------------------------------------------------------------------------------------
# Encouragement engine (Learn & Practice)
# ----------------------------------------------------------------------------------------------
PRAISE = ["That sign was clear and well formed.", "Exactly right.", "Clean handshape — well done.", "Correct, and nicely paced.",
          "A confident sign.", "Spot on.", "Well done. Keep the streak going."]
CLOSE = ["Close. One more try.", "Almost there — a small adjustment will do it.", "Good effort. Watch the reference once more."]
RETRY = ["Take another look at the reference, then try again.", "Slow down and give the sign room — go again.",
         "Watch the reference first, then sign it once more."]
LEVELS = [(0, "Beginner"), (50, "Explorer"), (150, "Communicator"), (300, "Fluent signer"), (600, "Setu champion")]


def level_for(xp):
    cur = LEVELS[0]
    nxt = None
    for i, lv in enumerate(LEVELS):
        if xp >= lv[0]:
            cur = lv
            nxt = LEVELS[i + 1] if i + 1 < len(LEVELS) else None
    return cur, nxt


def encouragement(score, rng=random):
    if score >= 0.6:
        return rng.choice(PRAISE)
    if score >= 0.25:
        return rng.choice(CLOSE)
    return rng.choice(RETRY)


def coach_tips(ref_base, try_base):
    """Concrete, landmark-derived feedback comparing an attempt (T,252) to a reference clip (T,252)."""
    tips = []
    ref, att = ref_base.reshape(-1, 4, 21, 3), try_base.reshape(-1, 4, 21, 3)

    def pres(x):
        return (abs(x[:, 2]).sum((-1, -2)) > 0).mean(), (abs(x[:, 3]).sum((-1, -2)) > 0).mean()
    ra, rb = pres(ref)
    ta, tb = pres(att)
    ref_two = min(ra, rb) > 0.3
    att_two = min(ta, tb) > 0.3
    if ref_two and not att_two:
        tips.append("This sign uses **both hands** — bring your second hand into view.")
    elif att_two and not ref_two:
        tips.append("This sign uses **one hand** — rest the other hand below your chest.")
    if max(ta, tb) < 0.4:
        tips.append("Your hands were visible only briefly — sign a little **slower** and keep hands inside the frame.")

    def mean_pos(x):
        m = abs(x[:, 2:4]).sum(-1).sum(-1) > 0
        if m.sum() == 0:
            return None
        return (x[:, 2:4, 0, :2][m]).mean(0)
    rp, tp = mean_pos(ref), mean_pos(att)
    if rp is not None and tp is not None:
        dy, dx = tp[1] - rp[1], tp[0] - rp[0]
        if dy > 1.0:
            tips.append("Raise your hand — the sign is made **closer to your face**.")
        elif dy < -1.0:
            tips.append("Lower your hand a little — the sign sits **lower, near your chest**.")
        if abs(dx) > 1.2:
            tips.append("Keep the sign **more centred** in front of your body.")
    rv = abs(ref[1:] - ref[:-1]).mean()
    tv = abs(att[1:] - att[:-1]).mean()
    if tv < 0.5 * rv:
        tips.append("Add more **movement** — this sign is dynamic.")
    elif tv > 2.0 * rv and rv > 0:
        tips.append("Try a **calmer, steadier** motion — this sign has little movement.")
    return tips[:3]
